"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { CalendarDays, ChevronLeft, ChevronRight, CircleDollarSign, Clock3, Download, LayoutDashboard, MessageCircle, Phone, Plus, Search, Send, Settings, UserRound, WalletCards, X } from "lucide-react";
import { addDays, format, isSameDay, startOfDay } from "date-fns";
import { ru } from "date-fns/locale";
import styles from "./page.module.css";

declare global { interface Window { Telegram?: { WebApp?: { initData: string; ready: () => void; expand: () => void; BackButton?: { show: () => void; hide: () => void; onClick: (callback: () => void) => void } } } } }
type Asset = { id: string; name: string; category: string; dailyRate: string | number; status: string; currentMileage?: number | null; serviceMileage?: number | null; serviceNote?: string | null; statusColor?: string };
type Booking = { id: string; assetId: string; clientName: string; clientPhone?: string; startDate: string; endDate: string; startTime?: string; endTime?: string; createdAt?: string; updatedAt?: string; dailyRate?: string | number; totalPrice: string | number; paidAmount: string | number; depositAmount?: string | number; status: string; asset?: Asset };
type Tab = "calendar" | "bookings" | "analytics" | "profile"; type Partner = { id: string; name: string; contactName?: string | null; phone?: string | null; contactChannel?: "PHONE" | "WHATSAPP" | "TELEGRAM"; email?: string | null; commissionType: string; commissionValue: string | number }; type TeamMember = { id: string; name: string; telegramId: string; phone?: string | null; email?: string | null; commissionPercent?: number; role: string; active: boolean };
const statusColors: Record<string, string> = { CONFIRMED: "blue", PENDING: "pink", PAID: "green", ACTIVE: "green", TECHNICAL: "yellow", CANCELLED: "gray" };
const days = Array.from({ length: 14 }, (_, index) => addDays(startOfDay(new Date()), index - 2));
type Analytics = { revenue: number; deposits: number; expenses: number; net: number; expected: number; bookings: number; commissionPercent?: number; commission?: number; isManager?: boolean; todayReturns?: Array<{ id: string; clientName: string; assetName: string; time: string; status: string }>; todayPickups?: Array<{ id: string; clientName: string; assetName: string; time: string; status: string }>; upcomingPayments?: Array<{ id: string; clientName: string; assetName: string; amount: number; date: string }>; serviceAssets?: Array<{ id: string; name: string; status: string; currentMileage: number | null; serviceMileage: number | null; serviceNote: string | null }>; rentalDays?: number; blockedDays?: number; byAsset?: Array<{ assetId: string; name: string; rentalDays: number; blockedDays: number; income: number; expenses: number; profit: number; bookings: number; monthlyIdle?: number }> };
const initialAnalytics: Analytics = { revenue: 0, deposits: 0, expenses: 0, net: 0, expected: 0, bookings: 0, rentalDays: 0, blockedDays: 0, byAsset: [], todayReturns: [], todayPickups: [], upcomingPayments: [], serviceAssets: [] };

export default function Home() {
  const [tab, setTab] = useState<Tab>("calendar"); const [bookingView, setBookingView] = useState<"active" | "past" | "archive">("active"); const [archivedBookings, setArchivedBookings] = useState<Booking[]>([]); const [darkMode, setDarkMode] = useState(false); const [bookingSeed, setBookingSeed] = useState<{ assetId: string; startDate: string; endDate: string } | null>(null); const [calendarSelection, setCalendarSelection] = useState<{ assetId: string; date: string } | null>(null); const [loggingOut, setLoggingOut] = useState(false); const [editingAsset, setEditingAsset] = useState<Asset | null>(null); const [showGuide, setShowGuide] = useState(false); const [hintsEnabled, setHintsEnabled] = useState(true); const [partners, setPartners] = useState<Partner[]>([]); const [team, setTeam] = useState<TeamMember[]>([]); const [dragAsset, setDragAsset] = useState<string | null>(null); const [assets, setAssets] = useState<Asset[]>([]); const [bookings, setBookings] = useState<Booking[]>([]); const [analytics, setAnalytics] = useState(initialAnalytics); const [search, setSearch] = useState(""); const [profileSearch, setProfileSearch] = useState(""); const [modal, setModal] = useState<"booking" | "asset" | "payment" | "partner" | "team" | null>(null); const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null); const [toast, setToast] = useState(""); const [authRequired, setAuthRequired] = useState(false); const [loading, setLoading] = useState(true);
  const api = useCallback(async (path: string, options?: RequestInit) => { const initData = window.Telegram?.WebApp?.initData; const headers = new Headers(options?.headers); headers.set("content-type", "application/json"); if (initData) headers.set("x-telegram-init-data", initData); const response = await fetch(path, { ...options, cache: "no-store", credentials: "include", headers }); const body = await response.json().catch(() => ({})); if (!response.ok) { if (response.status === 401) setAuthRequired(true); throw new Error(body.error || "Не удалось выполнить действие"); } return body; }, []);
  const refresh = useCallback(async () => { setLoading(true); const results = await Promise.allSettled([api("/api/assets"), api("/api/bookings"), api("/api/analytics"), api("/api/partners"), api("/api/team")]); const [a, b, c, p, t] = results; if (a.status === "fulfilled") setAssets(a.value); if (b.status === "fulfilled") setBookings(b.value); if (c.status === "fulfilled") setAnalytics(c.value); if (p.status === "fulfilled") setPartners(p.value); if (t.status === "fulfilled") setTeam(t.value); if (results.every(result => result.status === "fulfilled")) setAuthRequired(false); setLoading(false); }, [api]);
  useEffect(() => { const savedHints = window.localStorage.getItem("rp_hints"); if (savedHints !== null) setHintsEnabled(savedHints === "true"); const savedTheme = window.localStorage.getItem("rp_theme"); if (savedTheme === "dark") setDarkMode(true); const webApp = window.Telegram?.WebApp; if (webApp) { webApp.ready(); webApp.expand(); } void refresh(); }, [refresh]);
  useEffect(() => { if (tab === "bookings" && bookingView === "archive") void api("/api/bookings?archived=true").then(setArchivedBookings).catch(() => setArchivedBookings([])); }, [tab, bookingView, api]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(""), 3500); return () => window.clearTimeout(timer); }, [toast]);
  const visibleBookings = bookingView === "archive" ? archivedBookings : bookings; const filteredBookings = useMemo(() => visibleBookings.filter(b => `${b.clientName} ${b.asset?.name ?? ""}`.toLowerCase().includes(search.toLowerCase())), [visibleBookings, search]);
  const currency = (value: string | number) => `${Number(value).toLocaleString("vi-VN")} ₫`;
  const downloadReport = async () => { try { const selectedPartner = window.prompt("Партнёр для отчёта (оставьте пустым для всех):", "")?.trim() || ""; const report = await api(`/api/reports${selectedPartner ? `?partner=${encodeURIComponent(selectedPartner)}` : ""}`); const selectedPayments = selectedPartner ? report.payments.filter((x: any) => String(x.partner || "").toLowerCase() === selectedPartner.toLowerCase()) : report.payments; const selectedTotals = selectedPartner ? (report.partnerTotals || []).filter((x: any) => String(x.partner || "").toLowerCase() === selectedPartner.toLowerCase()) : (report.partnerTotals || []); const rows = [...selectedPayments.map((x: any) => ["Платёж", x.date, x.type, x.amount, x.asset, x.partner || "—"]), ...report.expenses.map((x: any) => ["Расход", x.date, x.category, x.amount, x.asset, "—"])]; const partnerTotals = selectedTotals.map((x: any) => `<tr><td>${String(x.partner || "Без партнёра").replaceAll("<", "&lt;")}</td><td>${x.bookings}</td><td>${x.income}</td><td>${x.expected}</td></tr>`).join(""); const printWindow = window.open("", "_blank", "noopener,noreferrer"); if (!printWindow) throw new Error("Разрешите всплывающие окна для PDF-отчёта"); printWindow.document.write(`<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Отчёт бухгалтера</title><style>body{font:14px Arial;color:#102a43;padding:32px}h1{color:#087f9a}table{border-collapse:collapse;width:100%;margin-top:20px}th,td{border:1px solid #cbdbe2;padding:8px;text-align:left}th{background:#e8f7fb}@media print{button{display:none}}</style></head><body><h1>KARMA RENT — Отчёт бухгалтеру</h1><p>Сформирован: ${new Date().toLocaleString("ru-RU")}</p><table><thead><tr><th>Раздел</th><th>Дата</th><th>Тип</th><th>Сумма</th><th>Объект</th><th>Партнёр</th></tr></thead><tbody>${rows.map((row: unknown[]) => `<tr>${row.map(value => `<td>${String(value ?? "—").replaceAll("<", "&lt;")}</td>`).join("")}</tr>`).join("")}</tbody></table><h2>Отчёты по партнёрам</h2><table><thead><tr><th>Партнёр</th><th>Броней</th><th>Получено</th><th>Ожидается</th></tr></thead><tbody>${partnerTotals}</tbody></table><script>window.onload=()=>{window.print()}</script></body></html>`); printWindow.document.close(); setToast("Отчёт открыт для сохранения в PDF"); } catch (error) { setToast(error instanceof Error ? error.message : "Не удалось сформировать отчёт"); } };
  const moveAsset = async (assetId: string, direction: -1 | 1) => { const current = assets.findIndex(item => item.id === assetId); const target = current + direction; if (current < 0 || target < 0 || target >= assets.length) return; const next = [...assets]; const [item] = next.splice(current, 1); next.splice(target, 0, item); setAssets(next); try { await Promise.all(next.map((entry, index) => api("/api/assets", { method: "PATCH", body: JSON.stringify({ id: entry.id, sortOrder: index }) }))); setToast("Порядок сохранён"); } catch (error) { setToast(error instanceof Error ? error.message : "Не удалось сохранить порядок"); await refresh(); } };
  const reorder = async (targetId: string) => { if (!dragAsset || dragAsset === targetId) return; const next = [...assets]; const from = next.findIndex(item => item.id === dragAsset); const to = next.findIndex(item => item.id === targetId); const [moved] = next.splice(from, 1); next.splice(to, 0, moved); setAssets(next); try { await Promise.all(next.map((item, index) => api("/api/assets", { method: "PATCH", body: JSON.stringify({ id: item.id, sortOrder: index }) }))); setToast("Порядок объектов сохранён"); } catch (error) { setToast(error instanceof Error ? error.message : "Не удалось сохранить порядок"); await refresh(); } finally { setDragAsset(null); } };
  const bookingStyle = (booking: Booking, lane = 0) => { const start = days.findIndex(d => isSameDay(d, new Date(booking.startDate))); const end = days.findIndex(d => isSameDay(d, new Date(booking.endDate))); const span = Math.max(1, Math.max(end, start + 1) - Math.max(start, 0)); return { left: `calc(${Math.max(0, start)} * var(--day-width))`, width: `calc(${span} * var(--day-width) - 8px)`, top: `${6 + (lane % 3) * 24}px` }; };
  const closeModal = () => { setModal(null); setSelectedBooking(null); };
  const title = tab === "calendar" ? format(new Date(), "LLLL yyyy", { locale: ru }) : tab === "bookings" ? "Бронирования" : tab === "analytics" ? "Аналитика и финансы" : "Профиль";
  return <main className={`${styles.shell} ${darkMode ? styles.dark : ""}`}>
    <header className={styles.header}><div><p className={styles.eyebrow}>RENTAL PLANNER</p><h1>{title}</h1></div><button className={styles.iconButton} onClick={() => setTab("profile")} aria-label="Настройки" title="Открыть профиль и настройки"><Settings size={18} /></button><HelpTip text="Откройте профиль, чтобы управлять байками, командой, темой и подсказками." /></header>
    {authRequired && <><div className={styles.authNotice}>Войдите через Telegram Mini App или используйте email/пароль владельца.</div><LoginPanel api={api} onDone={async () => { setAuthRequired(false); await refresh(); }} /></>}
    {tab === "calendar" && <section className={styles.dashboardStrip}><div className={styles.dashboardTitle}><div><p className={styles.eyebrow}>СЕГОДНЯ</p><h2>Контроль проката</h2></div><span>{format(new Date(), "d MMMM", { locale: ru })}</span></div><div className={styles.messagePanel}><div className={styles.messagePanelHead}><b>Важные сообщения</b><span>{(analytics.todayReturns?.length ?? 0) + (analytics.todayPickups?.length ?? 0) + (analytics.serviceAssets?.length ?? 0)}</span></div><div className={styles.messageList}>{(analytics.todayReturns ?? []).slice(0, 2).map(item => <div className={styles.messageItem} key={`return-${item.id}`}><span className={styles.messageDot} style={{ background: "#ef9daf" }} /><div><b>Возврат сегодня</b><small>{item.assetName} · {item.clientName}</small></div></div>)}{(analytics.todayPickups ?? []).slice(0, 2).map(item => <div className={styles.messageItem} key={`pickup-${item.id}`}><span className={styles.messageDot} style={{ background: "#50b8ed" }} /><div><b>Выдача сегодня</b><small>{item.assetName} · {item.clientName}</small></div></div>)}{(analytics.serviceAssets ?? []).slice(0, 2).map(item => <div className={styles.messageItem} key={`service-${item.id}`}><span className={styles.messageDot} style={{ background: "#e6bd53" }} /><div><b>Проверить байк</b><small>{item.name} · {item.serviceNote || "достигнут сервисный пробег"}</small></div></div>)}{(analytics.todayReturns?.length ?? 0) + (analytics.todayPickups?.length ?? 0) + (analytics.serviceAssets?.length ?? 0) === 0 && <div className={styles.messageEmpty}>На сегодня важных сообщений нет</div>}</div></div></section>}
    {tab === "calendar" && <section className={styles.content}><div className={styles.toolbar}><button className={styles.roundButton}><ChevronLeft size={18} /></button><button className={styles.todayButton}>Сегодня</button><button className={styles.roundButton}><ChevronRight size={18} /></button><span className={styles.helpWrap}><button className={styles.primaryButton} onClick={() => { setBookingSeed(null); setCalendarSelection(null); setModal("booking"); }}><Plus size={18} /> Бронь</button><HelpTip text="Создаёт новую бронь: выберите байк, клиента, даты и оплату." /></span></div><div className={styles.legend}><span><i className={styles.blueDot} /> подтверждена</span><span><i className={styles.pinkDot} /> ожидает</span><span><i className={styles.greenDot} /> оплачена</span></div><div className={styles.timeline}><div className={styles.timelineHead}><div className={styles.assetHead}>Объект</div><div className={styles.days}>{days.map(day => <div className={`${styles.day} ${isSameDay(day, new Date()) ? styles.currentDay : ""}`} key={day.toISOString()}><b>{format(day, "d")}</b><small>{format(day, "EEEEE", { locale: ru })}</small></div>)}</div></div>{assets.map(asset => <div className={styles.timelineRow} draggable key={asset.id} onDragStart={() => setDragAsset(asset.id)} onDragOver={e => e.preventDefault()} onDrop={() => void reorder(asset.id)}><div className={styles.assetCell}><b>{asset.name}</b><small>{asset.category === "SCOOTER" ? "Скутер" : asset.category === "MOTORCYCLE" ? "Мотоцикл" : asset.category} · {asset.status}</small></div><div className={styles.track}>{days.map(day => <button type="button" className={`${styles.gridCell} ${isSameDay(day, new Date()) ? styles.todayColumn : ""} ${calendarSelection?.assetId === asset.id && calendarSelection.date === format(day, "yyyy-MM-dd") ? styles.selectedCell : ""}`} key={day.toISOString()} aria-label={`Создать бронь: ${asset.name}, ${format(day, "d MMMM", { locale: ru })}`} onClick={() => { const date = format(day, "yyyy-MM-dd"); if (!calendarSelection || calendarSelection.assetId !== asset.id) { setCalendarSelection({ assetId: asset.id, date }); setToast(`Начало аренды: ${format(day, "d MMMM", { locale: ru })}. Выберите дату окончания.`); } else { const start = calendarSelection.date <= date ? calendarSelection.date : date; const finish = calendarSelection.date <= date ? date : calendarSelection.date; setBookingSeed({ assetId: asset.id, startDate: start, endDate: finish }); setCalendarSelection(null); setModal("booking"); } }} />)}{bookings.filter(b => b.assetId === asset.id).map((booking, bookingIndex) => <button className={`${styles.bookingBar} ${styles[statusColors[booking.status] ?? "gray"]} ${new Date(booking.updatedAt || booking.createdAt || booking.startDate).getTime() - new Date(booking.createdAt || booking.startDate).getTime() > 60000 ? styles.editedBooking : ""}`} style={bookingStyle(booking, bookingIndex)} key={booking.id} onClick={event => { event.stopPropagation(); setSelectedBooking(booking); setModal("payment"); }}>{booking.clientName}</button>)}</div></div>)}{assets.length === 0 && <div className={styles.emptyState}><CalendarDays size={24} /><b>{loading ? "Загрузка…" : "Объекты ещё не добавлены"}</b><span>{authRequired ? "Авторизуйтесь внутри Telegram." : "Добавьте первый объект в профиле."}</span></div>}</div></section>}
    {tab === "bookings" && <section className={styles.content}><div className={styles.sectionActions}><div className={styles.searchBox}><Search size={18} /><input placeholder="Поиск клиента или объекта" value={search} onChange={e => setSearch(e.target.value)} /></div><button className={styles.primaryButton} onClick={() => { setBookingSeed(null); setCalendarSelection(null); setModal("booking"); }}><Plus size={17} /> Бронь</button></div><div className={styles.tabs}><button className={bookingView === "active" ? styles.activeTab : ""} onClick={() => setBookingView("active")}>Актуальные</button><button className={bookingView === "past" ? styles.activeTab : ""} onClick={() => setBookingView("past")}>Прошедшие</button><button className={bookingView === "archive" ? styles.activeTab : ""} onClick={() => setBookingView("archive")}>Архив</button></div><div className={styles.cards}>{filteredBookings.map(b => <article className={styles.bookingCard} key={b.id} onClick={() => { setSelectedBooking(b); setModal("payment"); }}><div className={styles.cardTop}><div><b>{b.clientName}</b><span>{b.asset?.name ?? "Объект"}</span></div><em className={styles[`badge_${statusColors[b.status] ?? "gray"}`]}>{b.status === "CONFIRMED" ? "Подтверждена" : b.status}</em></div><div className={styles.cardMeta}><span><Clock3 size={14} /> {format(new Date(b.startDate), "d MMM", { locale: ru })} — {format(new Date(b.endDate), "d MMM", { locale: ru })}</span><strong>{currency(b.totalPrice)}</strong></div><div className={styles.paymentLine}><span>Оплачено {currency(b.paidAmount)}</span><span>Остаток {currency(Number(b.totalPrice) - Number(b.paidAmount))}</span></div></article>)}{filteredBookings.length === 0 && <div className={styles.emptyState}><b>Бронирований нет</b><span>Создайте бронь кнопкой выше.</span></div>}</div></section>}
    {tab === "analytics" && <section className={styles.content}><div className={styles.metricGrid}><Metric title={analytics.isManager ? `Моя комиссия · ${analytics.commissionPercent ?? 0}%` : "Выручка"} value={currency(analytics.isManager ? (analytics.commission ?? 0) : analytics.revenue)} icon={<CircleDollarSign />} accent="cyan" /><Metric title="Ожидается" value={currency(analytics.expected)} icon={<Clock3 />} accent="orange" /><Metric title={analytics.isManager ? "Объектов в парке" : "Расходы"} value={analytics.isManager ? String(analytics.byAsset?.length ?? 0) : currency(analytics.expenses)} icon={<WalletCards />} accent="pink" /><Metric title={analytics.isManager ? "Важных сообщений" : "Чистая прибыль"} value={analytics.isManager ? String((analytics.todayReturns?.length ?? 0) + (analytics.todayPickups?.length ?? 0) + (analytics.serviceAssets?.length ?? 0)) : currency(analytics.net)} icon={<CircleDollarSign />} accent="green" /></div><div className={styles.analyticsExplain}><div><b>Как читать этот раздел <HelpTip text="Здесь руководитель видит деньги, загрузку, простой и доходность каждого объекта. Менеджер видит только свою комиссию и рабочую информацию по парку." /></b><p>Здесь собраны деньги и загрузка парка по сохранённым бронированиям. Суммы показаны в ₫, а комиссия менеджера — только в рамках его процента.</p></div><div className={styles.explainGrid}><span><b>Выручка</b> — уже полученные платежи за аренду.</span><span><b>Ожидается</b> — сколько ещё должны заплатить по броням.</span><span><b>Расходы</b> — расходы, внесённые в CRM.</span><span><b>Чистая прибыль</b> — выручка минус расходы.</span><span><b>Арендные дни</b> — сколько суток байки были заняты.</span><span><b>Простой</b> — свободные дни конкретного байка в текущем месяце.</span></div></div><div className={styles.analyticsSummary}><div><span>Полученные залоги <HelpTip text="Деньги, полученные как залог и ещё не возвращённые клиенту." /></span><b>{currency(analytics.deposits)}</b></div><div><span>Бронирований <HelpTip text="Количество активных и завершённых бронирований без отменённых." /></span><b>{analytics.bookings}</b></div><div><span>Арендных дней <HelpTip text="Суммарное количество дней, когда байки были заняты арендой." /></span><b>{analytics.rentalDays ?? 0}</b></div><div><span>Дней блокировки <HelpTip text="Дни, когда объект был закрыт для аренды из-за ремонта или другой причины." /></span><b>{analytics.blockedDays ?? 0}</b></div></div><div className={styles.panel}><div className={styles.panelTitle}><div><b>Доходность объектов</b><span>выручка · расходы · прибыль</span></div>{!analytics.isManager && <button className={styles.reportButton} onClick={() => void downloadReport()}><Download size={15} /> PDF-отчёт</button>}</div>{(analytics.byAsset ?? []).map((row: { assetId: string; name: string; rentalDays: number; blockedDays: number; income: number; expenses: number; profit: number; bookings: number; monthlyIdle?: number }) => <div className={styles.assetAnalytics} key={row.assetId}><div><b>{row.name}</b><small>{row.bookings} броней · {row.rentalDays} арендных дней · {row.blockedDays} дней блокировки · простой в месяце: {row.monthlyIdle ?? 0} дн.</small></div><div><strong>{currency(row.profit)}</strong><small>доход {currency(row.income)} · расходы {currency(row.expenses)}</small></div></div>)}{(!analytics.byAsset || analytics.byAsset.length === 0) && <div className={styles.emptyState}><b>Недостаточно данных</b><span>Создайте объект и бронирование, чтобы увидеть загрузку и прибыль.</span></div>}</div></section>}
    {tab === "profile" && <section className={styles.content}>
      <div className={styles.profileSectionHeader}><div><p className={styles.eyebrow}>УПРАВЛЕНИЕ</p><h2>Мой бизнес</h2></div><div className={styles.headerActions}><label className={styles.compactSwitch} title="Показывать короткие подсказки"><input type="checkbox" checked={hintsEnabled} onChange={e => { setHintsEnabled(e.target.checked); window.localStorage.setItem("rp_hints", String(e.target.checked)); }} /><span>Подсказки</span></label><label className={styles.compactSwitch} title="Переключить тёмную тему"><input type="checkbox" checked={darkMode} onChange={e => { setDarkMode(e.target.checked); window.localStorage.setItem("rp_theme", e.target.checked ? "dark" : "light"); }} /><span>Тёмная тема</span></label><button className={styles.secondaryButtonSmall} onClick={async () => { setLoggingOut(true); await fetch("/api/auth/logout", { method: "POST" }); window.setTimeout(() => window.location.reload(), 500); }}>Выйти</button><span className={styles.helpWrap}><button className={styles.primaryButton} onClick={() => { setEditingAsset(null); setModal("asset"); }}><Plus size={16} /> Добавить</button><HelpTip text="Добавляет байк в парк. После сохранения он появляется в календаре и списке брони." /></span></div></div>
      <div className={styles.profileSearch}><div className={styles.searchBox}><Search size={18} /><input placeholder="Поиск по байкам, партнёрам и команде" value={profileSearch} onChange={e => setProfileSearch(e.target.value)} /><HelpTip text="Поиск по названию, телефону, email или имени. Это удобно для большого парка и сотен партнёров." /></div></div><div className={styles.profileGroup}><div className={styles.profileGroupTitle}><b>Мой автопарк <HelpTip text="Все байки и автомобили. Поиск выше скрывает остальные записи." /></b><span>{assets.length} объектов</span></div>{assets.filter(asset => `${asset.name} ${asset.category} ${asset.status}`.toLowerCase().includes(profileSearch.toLowerCase())).map(asset => <div className={styles.manageRow} key={asset.id}><div><b>{asset.name}</b><span>{asset.category === "SCOOTER" ? "Скутер" : asset.category === "MOTORCYCLE" ? "Мотоцикл" : asset.category} · {asset.status}</span></div><div className={styles.rowActions}><button className={styles.orderButton} title="Выше" onClick={() => void moveAsset(asset.id, -1)}>↑</button><button className={styles.orderButton} title="Ниже" onClick={() => void moveAsset(asset.id, 1)}>↓</button><button className={styles.editButton} onClick={() => { setEditingAsset(asset); setModal("asset"); }}>Редактировать</button><button className={styles.deleteButton} onClick={async () => { if (confirm(`Удалить ${asset.name}?`)) { await api("/api/assets", { method: "DELETE", body: JSON.stringify({ id: asset.id }) }); await refresh(); } }}>Удалить</button></div></div>)}{assets.length === 0 && <div className={styles.emptyState}><b>Автопарк пуст</b><span>Нажмите «Добавить» и сохраните первый байк.</span></div>}</div>
      <div className={styles.profileGroup}><div className={styles.profileGroupTitle}><b>Партнёры <HelpTip text="Партнёры находятся в отдельном списке. Используйте поиск выше." /></b><button className={styles.linkButton} onClick={() => setModal("partner")}>+ Добавить</button></div>{partners.filter(partner => `${partner.name} ${partner.contactName || ""} ${partner.phone || ""} ${partner.email || ""}`.toLowerCase().includes(profileSearch.toLowerCase())).map(partner => <div className={styles.manageRow} key={partner.id}><div><b>{partner.name}</b><span>{partner.contactName || "Без контакта"} · {partner.phone || "Нет телефона"} · {partner.email || "без email"} · {partner.commissionValue}{partner.commissionType === "PERCENT" ? "%" : " ₫"}</span></div><div className={styles.contactActions}>{partner.phone && <a title="Позвонить" href={`tel:${partner.phone}`}><Phone size={15} /></a>}{partner.phone && partner.contactChannel === "WHATSAPP" && <a title="WhatsApp" target="_blank" rel="noreferrer" href={`https://wa.me/${partner.phone.replace(/\D/g, "")}`}><MessageCircle size={15} /></a>}{partner.phone && partner.contactChannel === "TELEGRAM" && <a title="Telegram" target="_blank" rel="noreferrer" href={`https://t.me/${partner.phone.replace(/^@/, "")}`}><Send size={15} /></a>}<button className={styles.deleteButton} onClick={async () => { if (confirm(`Удалить партнёра ${partner.name}?`)) { await api("/api/partners", { method: "DELETE", body: JSON.stringify({ id: partner.id }) }); await refresh(); } }}>Удалить</button></div></div>)}{partners.length === 0 && <span className={styles.mutedText}>Партнёров пока нет</span>}</div>
      <div className={styles.profileGroup}><div className={styles.profileGroupTitle}><b>Команда и права <HelpTip text="Управление менеджерами, бухгалтерами и доступами." /></b><button className={styles.linkButton} onClick={() => setModal("team")}>+ Добавить</button></div>{team.filter(member => `${member.name} ${member.phone || ""} ${member.email || ""} ${member.role}`.toLowerCase().includes(profileSearch.toLowerCase())).map(member => <div className={styles.manageRow} key={member.id}><div><b>{member.name}</b><span>{member.role} · {member.phone || "без телефона"} · {member.email || "без email"}{member.telegramId ? ` · Telegram ${member.telegramId}` : ""}</span></div><button className={styles.deleteButton} onClick={async () => { if (confirm(`Удалить ${member.name}?`)) { await api("/api/team", { method: "DELETE", body: JSON.stringify({ id: member.id }) }); await refresh(); } }}>Удалить</button></div>)}{team.length === 0 && <span className={styles.mutedText}>Менеджеров пока нет</span>}</div>
    </section>}
    <nav className={styles.bottomNav}>{([ ["calendar", CalendarDays, "Календарь"], ["bookings", LayoutDashboard, "Брони"], ["analytics", CircleDollarSign, "Аналитика"], ["profile", UserRound, "Профиль"] ] as const).map(([key, Icon, label]) => <button key={key} className={tab === key ? styles.navActive : ""} onClick={() => setTab(key)}><Icon size={20} /><span>{label}</span></button>)}</nav>
    {modal === "booking" && <BookingModal key={`${bookingSeed?.assetId ?? "new"}-${bookingSeed?.startDate ?? "today"}`} assets={assets} partners={partners} initialAssetId={bookingSeed?.assetId} initialDate={bookingSeed?.startDate} initialEndDate={bookingSeed?.endDate} api={api} onClose={closeModal} onDone={async message => { closeModal(); setToast(message); await refresh(); }} />}
    {modal === "asset" && <AssetModal key={editingAsset?.id ?? "new"} asset={editingAsset} api={api} onClose={() => { setEditingAsset(null); closeModal(); }} onDone={async message => { setEditingAsset(null); closeModal(); setToast(message); await refresh(); }} />}
    {modal === "payment" && selectedBooking && <PaymentModal booking={selectedBooking} api={api} onClose={closeModal} onDone={async message => { closeModal(); setToast(message); await refresh(); }} currency={currency} />}
    {modal === "partner" && <PartnerModal api={api} onClose={closeModal} onDone={async message => { closeModal(); setToast(message); await refresh(); }} />}
    {modal === "team" && <TeamModal api={api} onClose={closeModal} onDone={async message => { closeModal(); setToast(message); await refresh(); }} />}
    {loggingOut && <div className={styles.logoutScreen}><img src="/karmarent-logo.png" alt="Karma Rent" /><b>До встречи</b><span>Сеанс завершается…</span></div>}
    {toast && <div className={styles.toast}>{toast}</div>}
  </main>;
}
function LoginPanel({ api, onDone }: { api: (path: string, options?: RequestInit) => Promise<any>; onDone: () => Promise<void> }) { const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [showPassword, setShowPassword] = useState(false); const [error, setError] = useState(""); return <div className={styles.loginPanel}><div className={styles.loginCard}><img className={styles.loginLogo} src="/karmarent-logo.png" alt="Karma Rent" /><p className={styles.eyebrow}>KARMA RENT</p><h2>Вход в приложение</h2><p>Можно работать через обычный браузер. Telegram остаётся быстрым входом внутри Mini App.</p><label>Email<input type="email" autoComplete="off" value={email} onChange={e => setEmail(e.target.value)} placeholder="owner@example.com" /></label><label>Пароль<div className={styles.passwordField}><input type={showPassword ? "text" : "password"} autoComplete="new-password" value={password} onChange={e => setPassword(e.target.value)} /><button type="button" className={styles.showPasswordButton} onClick={() => setShowPassword(value => !value)}>{showPassword ? "Скрыть" : "Показать"}</button></div></label>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e => { e.preventDefault(); setError(""); try { await api("/api/auth/login", { method: "POST", body: JSON.stringify({ email: email.trim(), password }) }); await onDone(); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось войти"); } }}>Войти</button></div></div>; }
function HelpTip({ text }: { text: string }) { const [open, setOpen] = useState(false); return <span className={styles.helpTip}><button type="button" className={styles.helpButton} aria-label="Подсказка" onClick={() => setOpen(value => !value)}>?</button>{(open || undefined) && <span className={styles.helpPopover}>{text}</span>}</span>; }
function Metric({ title, value, icon, accent }: { title: string; value: string; icon: React.ReactNode; accent: string }) { const help = title.includes("Выручка") ? "Фактически полученные платежи по аренде." : title.includes("Ожидается") ? "Сумма, которую должны получить по активным бронированиям." : title.includes("Расходы") ? "Расходы, связанные с обслуживанием и работой парка." : title.includes("комиссия") ? "Сумма комиссии менеджера по его проценту от полученных платежей." : title.includes("Объектов") ? "Количество объектов, доступных менеджеру в парке." : "Доходы минус расходы за выбранный период."; return <div className={styles.metric}><div className={styles.metricTop}><div className={`${styles.metricIcon} ${styles[accent]}`}>{icon}</div><HelpTip text={help} /></div><span>{title}</span><strong>{value}</strong></div>; }
function ModalFrame({ title, eyebrow, children, onClose }: { title: string; eyebrow: string; children: React.ReactNode; onClose: () => void }) { return <div className={styles.modalBackdrop} onClick={onClose}><form className={styles.modal} onClick={e => e.stopPropagation()}><div className={styles.modalHeader}><div><p className={styles.eyebrow}>{eyebrow}</p><h2>{title}</h2></div><button type="button" onClick={onClose}><X size={18} /></button></div>{children}</form></div>; }
function BookingModal({ assets, partners, initialAssetId, initialDate, initialEndDate, api, onClose, onDone }: { assets: Asset[]; partners: Partner[]; initialAssetId?: string; initialDate?: string; initialEndDate?: string; api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void> }) { const [form, setForm] = useState({ assetId: initialAssetId ?? assets[0]?.id ?? "", partnerId: "", clientName: "", clientPhone: "", startDate: initialDate ?? format(new Date(), "yyyy-MM-dd"), endDate: initialEndDate ?? format(addDays(new Date(), 1), "yyyy-MM-dd"), startTime: format(new Date(), "HH:mm"), endTime: format(new Date(), "HH:mm"), dailyRate: "", paidAmount: "0", depositAmount: "100", depositCurrency: "₫", passportPhoto: true, mileageLimitPerDay: "100", phoneHolder: "Premium", helmetCount: "2", mileageAtHandover: "", fuelLevel: "", notes: "" }); const [error, setError] = useState(""); const set = (key: string, value: string | boolean) => setForm(prev => ({ ...prev, [key]: value })); const daysCount = Math.max(1, Math.ceil((new Date(`${form.endDate}T${form.endTime}`).getTime() - new Date(`${form.startDate}T${form.startTime}`).getTime()) / 86400000)); const total = daysCount * Number(form.dailyRate || 0); return <ModalFrame eyebrow="НОВАЯ БРОНЬ" title="Данные аренды" onClose={onClose}>{initialAssetId ? <div className={styles.selectedAsset}><span>Байк из календаря</span><b>{assets.find(a => a.id === form.assetId)?.name || "Объект"}</b><HelpTip text="Байк уже выбран нажатием на строку календаря. Здесь менять его не нужно." /></div> : <label>Объект<select required value={form.assetId} onChange={e => { set("assetId", e.target.value); const a = assets.find(item => item.id === e.target.value); if (a && Number(a.dailyRate) > 0) set("dailyRate", String(a.dailyRate)); else set("dailyRate", ""); }}>{assets.length === 0 && <option value="">Нет объектов</option>}{assets.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select></label>}<label>Партнёр <HelpTip text="Партнёр связывает бронь, акт и будущий отчёт. Можно оставить пустым." /><select value={form.partnerId} onChange={e => set("partnerId", e.target.value)}><option value="">Без партнёра</option>{partners.map(partner => <option key={partner.id} value={partner.id}>{partner.name}</option>)}</select></label><label>Имя клиента<input required value={form.clientName} onChange={e => set("clientName", e.target.value)} placeholder="Например, Алексей" /></label><label>Телефон<input required value={form.clientPhone} onChange={e => set("clientPhone", e.target.value)} placeholder="+7 900 000 00 00" /></label><div className={styles.formGrid}><label>Фото паспорта<select value={form.passportPhoto ? "yes" : "no"} onChange={e => set("passportPhoto", e.target.value === "yes")}><option value="no">Нет</option><option value="yes">Есть</option></select></label><label>Лимит км/сутки<input type="number" min="0" value={form.mileageLimitPerDay} onChange={e => set("mileageLimitPerDay", e.target.value)} placeholder="100" /></label></div><div className={styles.formGrid}><label>Держатель телефона<input value={form.phoneHolder} onChange={e => set("phoneHolder", e.target.value)} placeholder="Premium" /></label><label>Шлемы<input type="number" min="0" value={form.helmetCount} onChange={e => set("helmetCount", e.target.value)} placeholder="2" /></label></div><div className={styles.formGrid}><label>Пробег при выдаче<input type="number" min="0" value={form.mileageAtHandover} onChange={e => set("mileageAtHandover", e.target.value)} placeholder="67206" /></label><label>Бензин<input value={form.fuelLevel} onChange={e => set("fuelLevel", e.target.value)} placeholder="1/6" /></label></div><div className={styles.formGrid}><label>Начало<input type="date" required value={form.startDate} onChange={e => set("startDate", e.target.value)} /><input type="time" value={form.startTime} onChange={e => set("startTime", e.target.value)} /></label><label>Окончание<input type="date" required value={form.endDate} onChange={e => set("endDate", e.target.value)} /><input type="time" value={form.endTime} onChange={e => set("endTime", e.target.value)} /></label></div><label className={styles.daysControl}>Количество суток <HelpTip text="Сутки считаются от времени выдачи до такого же времени возврата. Например, 7.10 12:00 — 9.10 12:00 = 2 суток." /><select value={daysCount} onChange={e => { const value = Math.max(1, Number(e.target.value) || 1); set("endDate", format(addDays(new Date(form.startDate), value), "yyyy-MM-dd")); }}>{Array.from({ length: 365 }, (_, index) => index + 1).map(value => <option key={value} value={value}>{value} суток</option>)}</select></label><div className={styles.formGrid}><label>Ставка/день<input type="number" min="0" required value={form.dailyRate} onChange={e => set("dailyRate", e.target.value)} /></label><label>Депозит<input inputMode="decimal" value={form.depositAmount} onChange={e => set("depositAmount", e.target.value.replace(/[^0-9.,]/g, ""))} /></label><label>Валюта<select value={form.depositCurrency} onChange={e => set("depositCurrency", e.target.value)}><option value="₫">₫</option><option value="$">$</option><option value="€">€</option></select></label></div><div className={styles.calculated}>Дней: <b>{daysCount}</b> · Итого: <b>{total.toLocaleString("vi-VN")} ₫</b></div><label>Примечание <HelpTip text="Запишите дополнительные условия аренды, залога или договорённости с клиентом." /><textarea value={form.notes} onChange={e => set("notes", e.target.value)} placeholder="Дополнительные условия" /></label>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} disabled={!form.assetId} onClick={async e => { e.preventDefault(); try { await api("/api/bookings", { method: "POST", body: JSON.stringify({ ...form, partnerId: form.partnerId || undefined, dailyRate: Number(form.dailyRate), totalPrice: total, paidAmount: Number(form.paidAmount), depositAmount: Number(form.depositAmount), notes: form.notes, mileageLimitPerDay: form.mileageLimitPerDay === "" ? undefined : Number(form.mileageLimitPerDay), helmetCount: form.helmetCount === "" ? undefined : Number(form.helmetCount), mileageAtHandover: form.mileageAtHandover === "" ? undefined : Number(form.mileageAtHandover), status: "CONFIRMED" }) }); await onDone("Бронь создана"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось создать бронь"); } }}>Создать бронь</button></ModalFrame>; }
function AssetModal({ asset, api, onClose, onDone }: { asset?: Asset | null; api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void> }) { const [form, setForm] = useState({ name: asset?.name ?? "", category: asset?.category ?? "SCOOTER" }); const [error, setError] = useState(""); return <ModalFrame eyebrow="МОЙ АВТОПАРК" title={asset ? "Редактировать объект" : "Новый объект"} onClose={onClose}><p className={styles.formHint}>Здесь только карточка объекта. Ставка, даты и пробег вводятся при создании бронирования.</p><label>Название<input autoComplete="off" required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Honda PCX 125cc" /></label><label>Категория<select value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}><option value="SCOOTER">Скутер</option><option value="MOTORCYCLE">Мотоцикл</option><option value="CAR">Автомобиль</option><option value="REAL_ESTATE">Недвижимость</option><option value="OTHER">Другое</option></select></label>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e => { e.preventDefault(); try { await api("/api/assets", { method: asset ? "PATCH" : "POST", body: JSON.stringify({ name: form.name, category: form.category, ...(asset ? { id: asset.id } : {}) }) }); await onDone(asset ? "Объект обновлён" : "Объект добавлен"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось сохранить объект"); } }}>{asset ? "Сохранить изменения" : "Добавить объект"}</button></ModalFrame>; }
function PartnerModal({ api, onClose, onDone }: { api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void> }) { const [form, setForm] = useState({ name: "", contactName: "", phone: "", email: "", contactChannel: "PHONE", commissionType: "PERCENT", commissionValue: "" }); const [error, setError] = useState(""); return <ModalFrame eyebrow="ПАРТНЁРЫ" title="Новый партнёр" onClose={onClose}><label>Название<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Отель / агентство" /></label><label>Контактное лицо<input value={form.contactName} onChange={e => setForm({ ...form, contactName: e.target.value })} /></label><label>Телефон или username<input value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} placeholder="+849... или @username" /></label><label>Email<input name="partner-email" autoComplete="off" type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="partner@example.com" /></label><label>Канал связи<select value={form.contactChannel} onChange={e => setForm({ ...form, contactChannel: e.target.value })}><option value="PHONE">Обычный телефон</option><option value="WHATSAPP">WhatsApp</option><option value="TELEGRAM">Telegram</option></select></label><div className={styles.formGrid}><label>Тип комиссии<select value={form.commissionType} onChange={e => setForm({ ...form, commissionType: e.target.value })}><option value="PERCENT">Процент</option><option value="FIXED">Фиксированная</option></select></label><label>Комиссия<input type="number" min="0" value={form.commissionValue} onChange={e => setForm({ ...form, commissionValue: e.target.value })} /></label></div>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e => { e.preventDefault(); try { await api("/api/partners", { method: "POST", body: JSON.stringify({ ...form, commissionValue: Number(form.commissionValue) }) }); await onDone("Партнёр добавлен"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось добавить партнёра"); } }}>Сохранить партнёра</button></ModalFrame>; }
function TeamModal({ api, onClose, onDone }: { api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void> }) { const [form, setForm] = useState({ name: "", phone: "", telegramId: "", email: "", password: "", commissionPercent: "", role: "MANAGER" }); const [error, setError] = useState(""); return <ModalFrame eyebrow="КОМАНДА" title="Добавить менеджера" onClose={onClose}><label>Имя<input name="manager-name" autoComplete="off" required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label>Телефон<input name="manager-phone" autoComplete="off" type="tel" value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} placeholder="+84..." /></label><label>Telegram ID<input name="manager-telegram-id" autoComplete="off" inputMode="numeric" pattern="[0-9]*" value={form.telegramId} onChange={e => setForm({ ...form, telegramId: e.target.value.replace(/\D/g, "") })} placeholder="123456789" /></label><label>Email<input name="manager-email" autoComplete="off" type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="manager@example.com" /></label><label>Пароль<input name="manager-password" autoComplete="new-password" required type="password" minLength={6} value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} placeholder="минимум 6 символов" /></label><label>Процент менеджера<input type="number" min="0" max="100" value={form.commissionPercent} onChange={e => setForm({ ...form, commissionPercent: e.target.value })} placeholder="Например, 20" /></label><label>Роль<select value={form.role} onChange={e => setForm({ ...form, role: e.target.value })}><option value="MANAGER">Менеджер</option><option value="ADMIN">Администратор</option><option value="ACCOUNTANT">Бухгалтер</option></select></label>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e => { e.preventDefault(); try { await api("/api/team", { method: "POST", body: JSON.stringify({ ...form, telegramId: form.telegramId, commissionPercent: Number(form.commissionPercent || 0), permissions: { assets: true, bookings: true, analytics: true, expenses: false, team: form.role === "ADMIN", reports: form.role === "ACCOUNTANT" || form.role === "ADMIN" } }) }); await onDone("Участник команды добавлен"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось добавить участника"); } }}>Сохранить участника</button></ModalFrame>; }
function PaymentModal({ booking, api, onClose, onDone, currency }: { booking: Booking; api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void>; currency: (value: string | number) => string }) { const [amount, setAmount] = useState(""); const [error, setError] = useState(""); const [actUrl, setActUrl] = useState(""); const [actPartner, setActPartner] = useState(""); const [audit, setAudit] = useState<Array<{ id: string; actorName: string; actorRole?: string; reason?: string; createdAt: string }>>([]); const [reason, setReason] = useState(""); const [startDate, setStartDate] = useState(booking.startDate.slice(0, 10)); const [endDate, setEndDate] = useState(booking.endDate.slice(0, 10)); const [startTime, setStartTime] = useState(booking.startTime || "12:00"); const [endTime, setEndTime] = useState(booking.endTime || "12:00"); const [dailyRate, setDailyRate] = useState(String(booking.dailyRate || "0")); const [extensionDays, setExtensionDays] = useState("1"); useEffect(() => { void api(`/api/audit?entityId=${booking.id}`).then(setAudit).catch(() => setAudit([])); }, [api, booking.id]); const days = Math.max(1, Math.ceil((new Date(`${endDate}T${endTime}`).getTime() - new Date(`${startDate}T${startTime}`).getTime()) / 86400000)); const savePeriod = async (nextEnd = endDate) => { try { await api("/api/bookings", { method: "PATCH", body: JSON.stringify({ id: booking.id, startDate, endDate: nextEnd, startTime, endTime, dailyRate: Number(dailyRate), reason }) }); await onDone("Период брони обновлён"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось обновить период"); } }; const createAct = async () => { try { const result = await api("/api/acts", { method: "POST", body: JSON.stringify({ bookingId: booking.id, partnerName: actPartner }) }); setActUrl(result.url); await navigator.clipboard?.writeText(result.url); setError("Ссылка на акт скопирована"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось создать акт"); } }; return <ModalFrame eyebrow="БРОНИРОВАНИЕ" title={booking.clientName} onClose={onClose}><div className={styles.detailBox}><span>{booking.asset?.name}</span><b>{currency(booking.totalPrice)}</b><small>Сейчас: {booking.startDate.slice(0, 10)} — {booking.endDate.slice(0, 10)} · {booking.startTime || "12:00"}–{booking.endTime || "12:00"}</small></div><div className={styles.formGrid}><label>Выдача<input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} /><input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} /></label><label>Сдача<input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} /><input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} /></label></div><label>Ставка за сутки <HelpTip text="Изменение ставки меняет общую сумму брони и обязательно фиксируется в журнале." /><input type="number" min="0" value={dailyRate} onChange={e => setDailyRate(e.target.value)} /></label><label>Причина изменения <HelpTip text="Обязательно укажите, почему изменили дату, время или продлили бронь. Это попадёт в журнал контроля." /><input value={reason} onChange={e => setReason(e.target.value)} placeholder="Например: клиент продлил аренду" /></label><div className={styles.calculated}>Дней: <b>{days}</b> · Новая сумма: <b>{currency(days * Number(dailyRate || 0))}</b></div><div className={styles.buttonRow}><button className={styles.secondaryButton} type="button" onClick={() => void savePeriod()}>Сохранить изменения <HelpTip text="Сохраняет новые даты и время брони. Причина записывается в журнал контроля." /></button><div className={styles.extendBox}><label>Продлить на <HelpTip text="Выберите, на сколько дополнительных суток продлить бронь. После выбора нажмите кнопку продления." /><input inputMode="numeric" value={extensionDays} onChange={e => setExtensionDays(e.target.value.replace(/\D/g, "").slice(0, 3))} placeholder="Например, 10" /></label><button className={styles.secondaryButton} type="button" onClick={() => { const next = format(addDays(new Date(`${endDate}T${endTime}`), Number(extensionDays)), "yyyy-MM-dd"); setEndDate(next); }}>Продлить бронь</button></div></div>{audit.length > 0 && <div className={styles.auditPanel}><b>История изменений</b>{audit.map(item => <div className={styles.auditItem} key={item.id}><strong>{item.actorName} · {item.actorRole || ""}</strong><small>{new Date(item.createdAt).toLocaleString("ru-RU")}</small><span>Причина: {item.reason || "не указана"}</span></div>)}</div>}<button className={styles.deleteButton} type="button" onClick={async () => { if (!window.confirm("Переместить бронь в архив на 14 дней?")) return; try { await api(`/api/bookings?id=${booking.id}`, { method: "DELETE" }); await onDone("Бронь перемещена в архив на 14 дней"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось архивировать бронь"); } }}>Удалить бронь в архив</button><label>Партнёр в акте <HelpTip text="Напишите партнёра вручную. Это имя будет напечатано в акте передачи." /><input value={actPartner} onChange={e => setActPartner(e.target.value)} placeholder="Например: Nguyen Travel" /></label><button className={styles.secondaryButton} type="button" onClick={createAct}>Акт передачи · создать</button>{actUrl && <><a className={styles.actLink} href={actUrl} target="_blank" rel="noreferrer">Открыть акт</a><button type="button" className={styles.secondaryButton} onClick={async () => { await navigator.clipboard?.writeText(actUrl); setError("Ссылка на акт скопирована"); }}>Скопировать ссылку</button></>}<label>Сумма платежа<input type="number" min="1" value={amount} onChange={e => setAmount(e.target.value)} placeholder="100" /></label>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e => { e.preventDefault(); try { await api("/api/payments", { method: "POST", body: JSON.stringify({ bookingId: booking.id, amount: Number(amount), paymentType: "RENTAL", paymentMethod: "CASH" }) }); await onDone("Платёж добавлен"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось добавить платёж"); } }}>Добавить оплату</button></ModalFrame>; }
